G                D
Days go by too fast
Em               C
Moments never seem to last
G                D
But with you by my side
Em               C
I can take it all in stride
Bridge:
Am            D
When I'm feeling down
G             C
You turn my world around
Am            D
My heart beats for you
G             C
Forever and ever true";
// Split lyrics into separate sections
string[] sections = lyrics.Split(new string[] { "Verse", "Chorus", "Bridge" }, StringSplitOptions.RemoveEmptyEntries);
// Split each section into separate lines
string[][] lines = new string[sections.Length][];
for (int i = 0; i < sections.Length; i++)
{
    lines[i] = sections[i].Split(new string[] { "\r\n", "\n" }, StringSplitOptions.RemoveEmptyEntries);
}
// Split each line into separate chords
string[][][] chords = new string[sections.Length][][];
for (int i = 0; i < sections.Length; i++)
{
    chords[i] = new string[lines[i].Length][];
    for (int j = 0; j < lines[i].Length; j++)
    {
        chords[i][j] = lines[i][j].Split(new char[] { ' ' }, StringSplitOptions.RemoveEmptyEntries);
    }
}
// Print chord chart notation
