            Console.Write(chords[i][j][k] + " ");
        }
        Console.Write("| ");
    }
    Console.WriteLine();
}
```
This code will split the lyrics into separate sections (Verse, Chorus, Bridge), and then split each section into separate lines. It will then split each line into separate chords, and finally loop through each section, line, and chord to print the chord chart notation.
Note that this code assumes that each chord is separated by a space, and that each line is separated by a newline character. You may need to adjust the code to handle different formats.

