```R
# Initialize the board
board <- matrix(rep(" ", 9), nrow=3)
# Print the board
print_board <- function(board) {
  for (i in 1:nrow(board)) {
    cat("|")
    for (j in 1:ncol(board)) {
      cat(board[i, j], "|")
    }
    cat("\n")
  }
}
# Check for a winning combination
check_win <- function(board, symbol) {
  # Check rows
  for (i in 1:nrow(board)) {
    if (all(board[i,] == symbol)) {
      return(TRUE)
    }
  }
  # Check columns
  for (j in 1:ncol(board)) {
    if (all(board[,j] == symbol)) {
      return(TRUE)
    }
  }
  # Check diagonals
  if (all(diag(board) == symbol) || all(diag(board[,ncol(board):1]) == symbol)) {
    return(TRUE)
  }
  # No winning combination found
  return(FALSE)
}
# Check for a tie
check_tie <- function(board) {
  if (!any(board == " ")) {
    return(TRUE)
  }
  return(FALSE)
}
# Play the game
play_game <- function() {
  # Initialize the players
  players <- c("X", "O")
  current_player <- players[1]
  # Play until there is a winner or a tie
  while (TRUE) {
    # Print the board
    print_board(board)
    # Get the current player's move
    cat(paste0("Player ", current_player, "'s turn: "))
    move <- readline()
    row <- as.numeric(substr(move, 1, 1))
    col <- as.numeric(substr(move, 2, 2))
    # Check if the move is valid
    if (row < 1 || row > 3 || col < 1 || col > 3 || board[row, col] != " ") {
      cat("Invalid move. Try again.\n")
      next
    }
    # Update the board
    board[row, col] <- current_player
    # Check for a winning combination
    if (check_win(board, current_player)) {
      print_board(board)
      cat(paste0("Player ", current_player, " wins!\n"))
      break
    }
    # Check for a tie
    if (check_tie(board)) {
      print_board(board)
      cat("It's a tie!\n")
      break
    }
    # Switch to the other player
    current_player <- players[ifelse(current_player == players[1], 2, 1)]
  }
}
# Start the game
play_game()
```
To run the program, simply copy and paste the code into an R console or script and execute it. The program will prompt the players to enter their moves and will print the board after each move. If a player wins or the game ends in a tie, the program will print the result and exit.

