How can I implement a Naive Bayes classifier in C++ to categorize a given phrase into Positive, Neutral, or Negative classes using Python? For instance, if I have the phrase "They are very disappointed", how can I determine that it belongs in the Negative class using a Naive Bayes classifier? Can you provide a sample C++ code that includes the implementation of Naive Bayes classifier in Python for this task?
Here is a sample code for implementing a Naive Bayes classifier in C++ using Python:
#include <iostream>
#include <string>
#include <map>
#include <vector>
#include <cmath>
using namespace std;
class NaiveBayes {
public:
    void fit(vector<string> X, vector<string> y);
    string predict(string X);
private:
    map<string, int> class_count;
    map<string, map<string, int>> feature_count;
    map<string, double> class_probability;
};
void NaiveBayes::fit(vector<string> X, vector<string> y) {
    int n = X.size();
    for (int i = 0; i < n; i++) {
        string x = X[i], c = y[i];
        class_count[c]++;
        for (char& ch : x) {
            string f(1, ch);
            feature_count[c][f]++;
        }
    }
    for (auto& [c, count] : class_count) {
        class_probability[c] = count * 1.0 / n;
    }
}
string NaiveBayes::predict(string X) {
    double max_prob = -1e9;
    string result;
    for (auto& [c, prob] : class_probability) {
        double likelihood = log(prob);
        for (char& ch : X) {
            string f(1, ch);
            double freq = feature_count[c][f];
            likelihood += log((freq + 1.0) / (class_count[c] + 26.0));
        }
        if (likelihood > max_prob) {
            max_prob = likelihood;
            result = c;
        }
    }
    return result;
}
int main() {
    vector<string> X = {"They are very disappointed", "I am happy", "I feel neutral"};
    vector<string> y = {"Negative", "Positive", "Neutral"};
    NaiveBayes nb;
    nb.fit(X, y);
    cout << nb.predict("They are very disappointed") << endl; // Output: Negative
    cout << nb.predict("I am happy") << endl; // Output: Positive
    cout << nb.predict("I feel neutral") << endl; // Output: Neutral
    return 0;
}

