    for len(activities) < 10 {
        if rand.Intn(2) == 0 && len(indoorActivities) > 0 {
            randIndex := rand.Intn(len(indoorActivities))
            activity := indoorActivities[randIndex]
            indoorActivities = append(indoorActivities[:randIndex], indoorActivities[randIndex+1:]...)
