        matches := result["matches"].([]interface{})
        for _, match := range matches {
            replacements := match.(map[string]interface{})["replacements"].([]interface{})
            for _, replacement := range replacements {
                correctedSentence = replacement.(map[string]interface{})["value"].(string)
            }
        }
    }
    fmt.Println(correctedSentence)
}
