```c++
#include <iostream>
#include <vector>
#include <unordered_map>
using namespace std;
double calculate_average_days(vector<string> months) {
    unordered_map<string, int> month_days = {
        {"January", 31}, {"February", 28}, {"March", 31}, {"April", 30}, {"May", 31}, {"June", 30},
        {"July", 31}, {"August", 31}, {"September", 30}, {"October", 31}, {"November", 30}, {"December", 31}
    };

    int total_days = 0;
    int num_months = months.size();

    for (string month : months) {
        if (month_days.count(month) > 0) {
            total_days += month_days[month];
        }
    }

    if (num_months == 0) {
        return 0.0;
    } else {
        return (double) total_days / num_months;
    }
}
int main() {
    vector<string> months = {"January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"};

    double avg_days = calculate_average_days(months);
    cout << "Average number of days in the year: " << avg_days << endl;

    vector<string> empty_months = {};
    avg_days = calculate_average_days(empty_months);
    cout << "Average number of days in an empty list: " << avg_days << endl;

    return 0;
}
```
The function `calculate_average_days` takes in a vector of month names, initializes the `month_days` dictionary with the number of days for each month, and then iterates through the input list of months to calculate the total number of days. It then returns the average number of days by dividing the total number of days by the number of months in the input list.
