```csharp
using System;
using System.Collections.Generic;
namespace RandomTriangles
{
    class Triangle
    {
        public double Base { get; set; }
        public double Height { get; set; }
        public double Area { get { return 0.5 * Base * Height; } }
    }
    class Program
    {
        static void Main(string[] args)
        {
            int numTriangles;
            double baseMin, baseMax, heightMin, heightMax;
            // Get user input for number of triangles and range of values
            Console.Write("Enter the number of triangles to generate: ");
            numTriangles = int.Parse(Console.ReadLine());
            Console.Write("Enter the minimum base value: ");
            baseMin = double.Parse(Console.ReadLine());
            Console.Write("Enter the maximum base value: ");
            baseMax = double.Parse(Console.ReadLine());
            Console.Write("Enter the minimum height value: ");
            heightMin = double.Parse(Console.ReadLine());
            Console.Write("Enter the maximum height value: ");
            heightMax = double.Parse(Console.ReadLine());
            // Generate random triangles and add them to a list
            List<Triangle> triangles = new List<Triangle>();
            Random rand = new Random();
            for (int i = 0; i < numTriangles; i++)
            {
                double b = rand.NextDouble() * (baseMax - baseMin) + baseMin;
                double h = rand.NextDouble() * (heightMax - heightMin) + heightMin;
                Triangle t = new Triangle { Base = b, Height = h };
                triangles.Add(t);
            }
            // Sort the triangles by area in ascending order
            triangles.Sort((t1, t2) => t1.Area.CompareTo(t2.Area));
            // Print out the triangles and their areas
            Console.WriteLine("Triangles sorted by area in ascending order:");
            foreach (Triangle t in triangles)
            {
                Console.WriteLine("Base: {0}, Height: {1}, Area: {2}", t.Base, t.Height, t.Area);
            }
            Console.ReadLine();
        }
    }
}
```
This program defines a `Triangle` class with properties for the base, height, and area of the triangle. It then prompts the user for the number of triangles to generate and the range of values for the base and height. It uses a `Random` object to generate random base and height values for each triangle, calculates the area, and adds the triangle to a list. Finally, it sorts the list of triangles by area in ascending order and prints out the triangles and their areas.

