        $meal_foods = array_filter($foods, function($food) use ($meal_ratios) {
            return $food['type'] == array_keys($meal_ratios)[0];
        });
        $total_price = array_reduce($meal_foods, function($sum, $food) {
            return $sum + $food['price'];
        }, 0);
        $meal_ratios_sum = array_sum($meal_ratios);
        $meal_ratios = array_map(function($ratio) use ($meal_ratios_sum) {
            return $ratio / $meal_ratios_sum;
        }, $meal_ratios);
        $meal_ratios = array_map(function($ratio) use ($total_price) {
            return $ratio * $total_price;
        }, $meal_ratios);
        $ratios[$meal] = $meal_ratios;
    }
    return $ratios;
}
