Sure, I can help you with that. Here's a Python program that meets your requirements:
```python
import csv
import math
def fibonacci(n):
    if n <= 0:
        return []
    elif n == 1:
        return [0]
    elif n == 2:
        return [0, 1]
    else:
        seq = [0, 1]
        for i in range(2, n):
            seq.append(seq[i-1] + seq[i-2])
        return seq
def is_even(n):
    return n % 2 == 0
def is_prime(n):
    if n <= 1:
        return False
    elif n == 2:
        return True
    elif is_even(n):
        return False
    else:
        for i in range(3, int(math.sqrt(n))+1, 2):
            if n % i == 0:
                return False
        return True
def generate_table(seq):
    table = []
    for i, num in enumerate(seq):
        table.append([i+1, num, is_even(num), is_prime(num)])
    return table
def save_table(table):
    filename = input("Enter a filename to save the table as a CSV file: ")
    with open(filename, 'w', newline='') as csvfile:
        writer = csv.writer(csvfile)
        writer.writerow(["Term", "Fibonacci Number", "Even", "Prime"])
        for row in table:
            writer.writerow(row)
def main():
    while True:
        try:
            n = int(input("Enter the number of terms to generate: "))
            start = int(input("Enter the starting number (default is 0): ") or 0)
            step = int(input("Enter the step size (default is 1): ") or 1)
            break
        except ValueError:
            print("Invalid input. Please enter an integer.")
    seq = fibonacci(n)
    seq = [start + i*step for i in range(n)]  # apply custom parameters
    table = generate_table(seq)
    save_table(table)
    even_sum = sum(filter(is_even, seq))
    print("Sum of even numbers:", even_sum)
    prime_count = sum(map(is_prime, seq))
    print("Number of prime numbers:", prime_count)
if __name__ == "__main__":
    main()
```
